(() => {
  const STORAGE_KEY='hrflow_state_v1', SESSION_KEY='hrflow_session_v1';
  const DATA_FILES=['users','departments','employees','attendance','leaves','contracts','performance','onboarding','documents','announcements','audit','notifications','settings'];
  const ICONS={
    dashboard:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/></svg>',
    users:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
    dept:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 21h18"/><path d="M6 21V4h12v17"/><path d="M9 8h2M13 8h2M9 12h2M13 12h2M9 16h2M13 16h2"/></svg>',
    clock:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg>',
    calendar:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>',
    file:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16h16V8Z"/><path d="M14 2v6h6"/></svg>',
    star:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/></svg>',
    checklist:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 6h11M9 12h11M9 18h11"/><path d="m3 6 1.5 1.5L7 5m-4 7 1.5 1.5L7 11m-4 7 1.5 1.5L7 17"/></svg>',
    book:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5V4.5A2.5 2.5 0 0 1 6.5 2Z"/></svg>',
    megaphone:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m3 11 18-5v12L3 14Z"/><path d="M11.6 16.4 13 21H7l-1.2-6.2"/></svg>',
    org:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="3" width="6" height="5" rx="1"/><rect x="3" y="16" width="6" height="5" rx="1"/><rect x="15" y="16" width="6" height="5" rx="1"/><path d="M12 8v4M6 16v-4h12v4"/></svg>',
    chart:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 3v18h18"/><path d="M7 14v4M12 10v8M17 6v12"/></svg>',
    shield:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3 20 6v6c0 5-3.5 8-8 10-4.5-2-8-5-8-10V6Z"/><path d="m9 12 2 2 4-4"/></svg>',
    settings:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06A1.7 1.7 0 0 0 15 19.4a1.7 1.7 0 0 0-1 .6 1.7 1.7 0 0 0-.4 1V21H9v-.08a1.7 1.7 0 0 0-1.1-1.52 1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 3.6 15a1.7 1.7 0 0 0-.6-1 1.7 1.7 0 0 0-1-.4H2V9h.08A1.7 1.7 0 0 0 3.6 7.9a1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.83-2.83.06.06A1.7 1.7 0 0 0 8 3.6a1.7 1.7 0 0 0 1-.6A1.7 1.7 0 0 0 9.4 2H14v.08A1.7 1.7 0 0 0 15.1 3.6a1.7 1.7 0 0 0 1.88-.34l.06-.06 2.83 2.83-.06.06A1.7 1.7 0 0 0 20.4 8a1.7 1.7 0 0 0 .6 1 1.7 1.7 0 0 0 1 .4H22V14h-.08a1.7 1.7 0 0 0-1.52 1Z"/></svg>',
    search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/></svg>',
    plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>',
    eye:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>',
    edit:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 1 1 3 3L7 19l-4 1 1-4Z"/></svg>',
    trash:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6M10 11v6M14 11v6"/></svg>',
    sun:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>',
    moon:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.8A9 9 0 1 1 11.2 3c0 .3 0 .5.1.8A7 7 0 0 0 20.2 12c.3 0 .5 0 .8-.1Z"/></svg>',
    logout:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5M21 12H9"/></svg>',
    mail:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></svg>',
    lock:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>',
    menu:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16M4 12h16M4 18h16"/></svg>',
    close:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg>',
    bell:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 8a6 6 0 1 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>',
    save:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M17 21v-8H7v8M7 3v5h8"/></svg>'
  };

  const NAV=[
    ['Overview',[['dashboard','Dashboard','dashboard']]],
    ['People',[['employees','Empleados','users'],['departments','Departamentos','dept'],['org','Organigrama','org']]],
    ['Time & Leave',[['attendance','Asistencia','clock'],['leave','Vacaciones y licencias','calendar']]],
    ['Employment',[['contracts','Contratos','file'],['onboarding','Onboarding','checklist'],['documents','Documentos','book']]],
    ['Talent',[['performance','Evaluaciones','star'],['announcements','Comunicados','megaphone']]],
    ['Analytics',[['reports','Reportes','chart'],['audit','Auditoría','shield']]],
    ['System',[['settings','Configuración','settings']]]
  ];
  const META={dashboard:['Dashboard','Resumen general de la organización.'],employees:['Empleados','Expediente y directorio de colaboradores.'],departments:['Departamentos','Estructura, responsables y headcount.'],attendance:['Asistencia','Entradas, salidas, horas y puntualidad.'],leave:['Vacaciones y licencias','Solicitudes, saldos y aprobaciones.'],contracts:['Contratos','Condiciones laborales, vigencia y vencimientos.'],performance:['Evaluaciones','Desempeño, competencias y planes de desarrollo.'],onboarding:['Onboarding','Seguimiento de ingreso y plan 30-60-90.'],documents:['Documentos','Documentación laboral y vencimientos.'],announcements:['Comunicados','Noticias internas y mensajes segmentados.'],org:['Organigrama','Vista organizacional y dependencias.'],reports:['Reportes','Indicadores de personas, tiempo y talento.'],audit:['Auditoría','Trazabilidad de acciones y cambios.'],settings:['Configuración','Preferencias del workspace y respaldos.']};
  let state,currentUser,currentView='dashboard';
  const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const fmtDate=v=>!v?'—':new Date(v+'T00:00:00').toLocaleDateString('es-BO',{day:'2-digit',month:'short',year:'numeric'});
  const money=v=>new Intl.NumberFormat('es-BO',{style:'currency',currency:'BOB',maximumFractionDigits:0}).format(v||0);
  const emp=id=>state.employees.find(e=>e.id===Number(id));
  const dept=id=>state.departments.find(d=>d.id===Number(id));
  const user=id=>state.users.find(u=>u.id===Number(id));
  const nextId=a=>Math.max(0,...a.map(x=>Number(x.id)||0))+1;
  const save=()=>{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));localStorage.setItem(SESSION_KEY,JSON.stringify({userId:currentUser?.id||null,theme:state.settings.theme}))};
  function log(action,entity,detail){state.audit.unshift({id:nextId(state.audit),date:new Date().toLocaleString('sv-SE').replace('T',' ').slice(0,16),userId:currentUser?.id||1,action,entity,detail});state.audit=state.audit.slice(0,300)}
  function toast(msg,type='info'){const d=document.createElement('div');d.className=`toast ${type}`;d.textContent=msg;$('toastContainer').appendChild(d);setTimeout(()=>d.remove(),3200)}
  function chip(text){const t=String(text||'');let c='gray';if(/active|approved|present|completed|valid|published/i.test(t))c='green';else if(/pending|late|expiring|draft|progress|on leave/i.test(t))c='yellow';else if(/absent|rejected|expired|ended|inactive/i.test(t))c='red';else if(/remote|hybrid|full time/i.test(t))c='blue';else c='teal';return `<span class="chip chip-${c}">${esc(t)}</span>`}
  function can(action){const r=currentUser?.role||'';if(r==='HR Admin')return true;if(r==='HR Manager')return !['settings-admin'].includes(action);if(r==='Manager')return ['view','attendance','leave-approve','performance','reports','announcements'].includes(action);if(r==='Recruiter')return ['view','employees','onboarding','documents','announcements'].includes(action);if(r==='Payroll')return ['view','contracts','reports'].includes(action);if(r==='Employee')return ['view-self','leave-request','attendance-self'].includes(action);return false}
  async function load(){const stored=localStorage.getItem(STORAGE_KEY);if(stored){try{return JSON.parse(stored)}catch{}}try{const out={};for(const f of DATA_FILES){const r=await fetch(`json/${f}.json`);if(!r.ok)throw Error(f);out[f]=await r.json()}return out}catch{return JSON.parse(JSON.stringify(window.HRFLOW_SEED))}}
  function applyTheme(){document.body.classList.toggle('theme-dark',state.settings.theme==='dark');document.body.classList.toggle('theme-light',state.settings.theme!=='dark');$('themeToggle').innerHTML=state.settings.theme==='dark'?ICONS.sun:ICONS.moon}
  function injectIcons(){$('loginMailIcon').innerHTML=ICONS.mail;$('loginLockIcon').innerHTML=ICONS.lock;$('loginEnterIcon').innerHTML=ICONS.logout;$('shieldIcon').innerHTML=ICONS.shield;$('togglePassword').innerHTML=ICONS.eye;$('collapseSidebarBtn').innerHTML=ICONS.menu;$('mobileMenuBtn').innerHTML=ICONS.menu;$('globalCreateIcon').innerHTML=ICONS.plus;$('notificationIcon').innerHTML=ICONS.bell;$('commandIcon').innerHTML=ICONS.search;$('logoutBtn').innerHTML=ICONS.logout;$('closeModalBtn').innerHTML=ICONS.close;$('closeDrawerBtn').innerHTML=ICONS.close;$('commandSearchIcon').innerHTML=ICONS.search}
  function quickLogins(){const wrap=$('quickLoginGrid');wrap.innerHTML=state.users.map(u=>`<button type="button" class="quick-login-card" data-login="${u.id}"><div class="avatar">${esc(u.avatar)}</div><div><strong>${esc(u.role)}</strong><span>${esc(u.name)}</span></div></button>`).join('')}
  function counts(k){return {employees:state.employees.filter(e=>e.status==='Active').length,departments:state.departments.length,attendance:state.attendance.length,leave:state.leaves.filter(x=>x.status==='Pending').length,contracts:state.contracts.filter(x=>x.status==='Active').length,performance:state.performance.filter(x=>x.status!=='Completed').length,onboarding:state.onboarding.filter(x=>x.status!=='Completed').length,documents:state.documents.filter(x=>x.status==='Expiring').length,announcements:state.announcements.length,audit:state.audit.length}[k]??0}
  function allowedViews(){const r=currentUser?.role||'';if(['HR Admin','HR Manager'].includes(r))return NAV.flatMap(x=>x[1].map(i=>i[0]));if(r==='Manager')return ['dashboard','employees','attendance','leave','performance','announcements','reports'];if(r==='Recruiter')return ['dashboard','employees','departments','org','onboarding','documents','announcements'];if(r==='Payroll')return ['dashboard','employees','contracts','reports'];if(r==='Employee')return ['dashboard','attendance','leave','announcements'];return ['dashboard']}
  function renderNav(){const allowed=allowedViews();$('sidebarNav').innerHTML=NAV.map(([section,items])=>{const visible=items.filter(([k])=>allowed.includes(k));if(!visible.length)return '';return `<div class="nav-section">${section}</div>${visible.map(([k,l,i])=>`<button class="nav-item ${currentView===k?'active':''}" data-nav="${k}"><span class="nav-icon">${ICONS[i]}</span><span>${l}</span>${counts(k)?`<span class="nav-count">${counts(k)}</span>`:''}</button>`).join('')}`}).join('')}
  function context(){$('contextBar').innerHTML=`<div class="toolbar"><span class="context-chip">${state.settings.companyName}</span><span class="context-chip">Zona horaria: ${state.settings.timezone}</span><span class="context-chip">Jornada: ${state.settings.workdayStart}–${state.settings.workdayEnd}</span></div><div class="muted small">Última actualización: ${new Date().toLocaleString('es-BO')}</div>`}
  function switchView(k){if(currentUser&&!allowedViews().includes(k))return toast('Tu rol no tiene acceso a este módulo','error');currentView=k;document.querySelectorAll('.view').forEach(v=>v.classList.add('hidden'));$(`view-${k}`).classList.remove('hidden');$('pageTitle').textContent=META[k][0];$('breadcrumbText').textContent=`HRFlow / ${META[k][0]}`;renderNav();renderCurrent()}
  function kpi(label,value,foot,icon){return `<article class="kpi-card"><div class="kpi-top"><div><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div></div><div class="kpi-icon">${ICONS[icon]}</div></div><div class="kpi-foot"><span>${foot}</span></div></article>`}
  function attendanceRate(){const a=state.attendance;const present=a.filter(x=>['Present','Late'].includes(x.status)).length;return a.length?Math.round(present/a.length*100):0}
  function renderDashboard(){const active=state.employees.filter(e=>e.status==='Active').length,pending=state.leaves.filter(l=>l.status==='Pending').length,expiring=state.contracts.filter(c=>c.endDate&&new Date(c.endDate)<=new Date('2026-12-31')&&c.status==='Active').length,avg=state.performance.filter(p=>p.status==='Completed').reduce((a,p)=>a+p.overall,0)/(state.performance.filter(p=>p.status==='Completed').length||1);const byDept=state.departments.map(d=>({d,count:state.employees.filter(e=>e.departmentId===d.id&&e.status!=='Inactive').length}));$('view-dashboard').innerHTML=`<div class="kpi-grid">${kpi('Headcount activo',active,'Personas activas','users')}${kpi('Asistencia',attendanceRate()+'%','Registros del mes','clock')}${kpi('Solicitudes pendientes',pending,'Vacaciones y licencias','calendar')}${kpi('Desempeño promedio',avg.toFixed(1)+'/5','Evaluaciones completadas','star')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Headcount por departamento</h3><p>Distribución actual de personas.</p></div></div><div class="list">${byDept.map(x=>`<div class="list-item"><div><h4>${esc(x.d.name)}</h4><p>${esc(x.d.location)}</p></div><strong>${x.count}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h3>Alertas de RR.HH.</h3><p>Elementos que requieren seguimiento.</p></div></div><div class="list"><div class="list-item"><div><h4>Solicitudes por aprobar</h4><p>Vacaciones y permisos pendientes.</p></div>${chip(pending+' pendientes')}</div><div class="list-item"><div><h4>Contratos con fecha fin</h4><p>Revisa vigencias registradas.</p></div>${chip(expiring+' contratos')}</div><div class="list-item"><div><h4>Documentos por vencer</h4><p>Documentación con expiración próxima.</p></div>${chip(state.documents.filter(d=>d.status==='Expiring').length+' alertas')}</div></div></section></div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Solicitudes recientes</h3><p>Últimos movimientos de vacaciones/licencias.</p></div><button class="btn btn-secondary" data-nav="leave">Ver todas</button></div><div class="list">${state.leaves.slice(0,4).map(l=>`<div class="list-item"><div><h4>${esc(emp(l.employeeId)?.fullName||'Empleado')}</h4><p>${l.type} · ${fmtDate(l.startDate)} → ${fmtDate(l.endDate)}</p></div>${chip(l.status)}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h3>Onboarding</h3><p>Nuevas incorporaciones en seguimiento.</p></div><button class="btn btn-secondary" data-nav="onboarding">Abrir</button></div><div class="list">${state.onboarding.map(o=>`<div class="list-item"><div style="flex:1"><h4>${esc(emp(o.employeeId)?.fullName||'Empleado')}</h4><p>Inicio ${fmtDate(o.startDate)} · Buddy ${esc(emp(o.buddyEmployeeId)?.fullName||'—')}</p><div class="progress"><span style="width:${o.progress}%"></span></div></div><strong>${o.progress}%</strong></div>`).join('')}</div></section></div>`}
  function actionButtons(kind,id,edit=true,del=true,doc=false){return `<div class="actions"><button class="action-btn action-view" data-view="${kind}" data-id="${id}" title="Ver">${ICONS.eye}</button>${edit?`<button class="action-btn action-edit" data-edit="${kind}" data-id="${id}" title="Editar">${ICONS.edit}</button>`:''}${doc?`<button class="action-btn action-doc" data-view="document" data-id="${id}" title="Documento">${ICONS.file}</button>`:''}${del?`<button class="action-btn action-delete" data-delete="${kind}" data-id="${id}" title="Eliminar">${ICONS.trash}</button>`:''}</div>`}
  function renderEmployees(){const rows=state.employees.map(e=>`<tr><td><div class="employee-cell"><div class="avatar">${esc(e.firstName[0]+e.lastName[0])}</div><div><strong>${esc(e.fullName)}</strong><span class="muted small">${esc(e.employeeCode)} · ${esc(e.email)}</span></div></div></td><td>${esc(e.position)}</td><td>${esc(dept(e.departmentId)?.name||'—')}</td><td>${chip(e.status)}</td><td>${esc(e.employmentType)}</td><td>${esc(e.workMode)}</td><td>${fmtDate(e.hireDate)}</td><td>${actionButtons('employee',e.id,can('employees'),can('employees'))}</td></tr>`).join('');$('view-employees').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Directorio de empleados</h2><p>Información laboral, contacto, modalidad y estado.</p></div>${can('employees')?`<button class="btn btn-primary" data-create="employee">${ICONS.plus} Nuevo empleado</button>`:''}</div><div class="toolbar"><input id="employeeSearch" class="search-control" placeholder="Buscar por nombre, cargo o código…"><select id="employeeDept"><option value="">Todos los departamentos</option>${state.departments.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select><select id="employeeStatus"><option value="">Todos los estados</option><option>Active</option><option>On Leave</option><option>Inactive</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Empleado</th><th>Cargo</th><th>Departamento</th><th>Estado</th><th>Tipo</th><th>Modalidad</th><th>Ingreso</th><th>Acciones</th></tr></thead><tbody id="employeeRows">${rows}</tbody></table></div></section>`;bindEmployeeFilters()}
  function bindEmployeeFilters(){const s=$('employeeSearch'),d=$('employeeDept'),st=$('employeeStatus');if(!s)return;const go=()=>{const q=s.value.toLowerCase(),dv=d.value,sv=st.value;document.querySelectorAll('#employeeRows tr').forEach((tr,i)=>{const e=state.employees[i];tr.style.display=((!q||`${e.fullName} ${e.position} ${e.employeeCode}`.toLowerCase().includes(q))&&(!dv||String(e.departmentId)===dv)&&(!sv||e.status===sv))?'':'none'})};s.oninput=go;d.onchange=go;st.onchange=go}
  function renderDepartments(){$('view-departments').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Departamentos</h2><p>Estructura organizacional, presupuesto y headcount.</p></div>${can('employees')?`<button class="btn btn-primary" data-create="department">${ICONS.plus} Nuevo departamento</button>`:''}</div><div class="cards">${state.departments.map(d=>{const hc=state.employees.filter(e=>e.departmentId===d.id&&e.status!=='Inactive').length;return `<article class="card"><div class="stat-row"><div><h3>${esc(d.name)}</h3><div class="muted small">${esc(d.code)} · ${esc(d.location)}</div></div>${chip(d.status)}</div><div class="grid-2"><div><span class="muted small">Headcount</span><strong style="display:block;font-size:1.5rem">${hc}</strong></div><div><span class="muted small">Presupuesto</span><strong style="display:block">${money(d.budget)}</strong></div></div><div class="muted small">Responsable: ${esc(user(d.managerId)?.name||'Sin asignar')}</div>${actionButtons('department',d.id,can('employees'),can('employees'))}</article>`}).join('')}</div></section>`}
  function renderAttendance(){const today='2026-09-15';const recent=state.attendance.filter(a=>a.date>=today).slice(-80).reverse();$('view-attendance').innerHTML=`<div class="kpi-grid">${kpi('Asistencia mensual',attendanceRate()+'%','Presentes + llegadas tardías','clock')}${kpi('Llegadas tardías',state.attendance.filter(a=>a.status==='Late').length,'Registros del período','clock')}${kpi('Ausencias',state.attendance.filter(a=>a.status==='Absent').length,'Registros del período','calendar')}${kpi('Horas registradas',Math.round(state.attendance.reduce((s,a)=>s+(a.hours||0),0)),'Horas acumuladas','clock')}</div><section class="panel"><div class="panel-head"><div><h2>Registro de asistencia</h2><p>Entradas, salidas, horas y estado diario.</p></div>${can('attendance')?`<button class="btn btn-primary" data-create="attendance">${ICONS.plus} Registrar asistencia</button>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Empleado</th><th>Fecha</th><th>Entrada</th><th>Salida</th><th>Horas</th><th>Estado</th><th>Nota</th><th>Acciones</th></tr></thead><tbody>${recent.map(a=>`<tr><td>${esc(emp(a.employeeId)?.fullName||'—')}</td><td>${fmtDate(a.date)}</td><td>${a.checkIn||'—'}</td><td>${a.checkOut||'—'}</td><td>${a.hours??0}</td><td>${chip(a.status)}</td><td>${esc(a.note||'—')}</td><td>${actionButtons('attendance',a.id,can('attendance'),can('attendance'))}</td></tr>`).join('')}</tbody></table></div></section>`}
  function renderLeave(){$('view-leave').innerHTML=`<div class="kpi-grid">${kpi('Pendientes',state.leaves.filter(x=>x.status==='Pending').length,'Requieren aprobación','calendar')}${kpi('Aprobadas',state.leaves.filter(x=>x.status==='Approved').length,'Solicitudes aprobadas','calendar')}${kpi('Vacaciones',state.leaves.filter(x=>x.type==='Vacation').length,'Solicitudes registradas','calendar')}${kpi('Saldo promedio',Math.round(state.employees.reduce((s,e)=>s+e.leaveBalance,0)/state.employees.length),'Días disponibles','calendar')}</div><section class="panel"><div class="panel-head"><div><h2>Vacaciones y licencias</h2><p>Solicitudes, periodos, saldos y aprobación.</p></div><button class="btn btn-primary" data-create="leave">${ICONS.plus} Nueva solicitud</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Empleado</th><th>Tipo</th><th>Desde</th><th>Hasta</th><th>Días</th><th>Estado</th><th>Motivo</th><th>Acciones</th></tr></thead><tbody>${state.leaves.map(l=>`<tr><td>${esc(emp(l.employeeId)?.fullName||'—')}</td><td>${esc(l.type)}</td><td>${fmtDate(l.startDate)}</td><td>${fmtDate(l.endDate)}</td><td>${l.days}</td><td>${chip(l.status)}</td><td>${esc(l.reason)}</td><td><div class="actions">${l.status==='Pending'&&can('leave-approve')?`<button class="btn btn-primary" data-approve-leave="${l.id}">Aprobar</button><button class="btn btn-danger" data-reject-leave="${l.id}">Rechazar</button>`:actionButtons('leave',l.id,true,can('employees'))}</div></td></tr>`).join('')}</tbody></table></div></section>`}
  function renderContracts(){const exp=state.contracts.filter(c=>c.endDate&&new Date(c.endDate)<new Date('2027-01-01')&&c.status==='Active').length;$('view-contracts').innerHTML=`<div class="kpi-grid">${kpi('Contratos activos',state.contracts.filter(c=>c.status==='Active').length,'Vigentes','file')}${kpi('Indefinidos',state.contracts.filter(c=>c.type==='Indefinite').length,'Contratos sin fecha fin','file')}${kpi('Próximos a vencer',exp,'Requieren seguimiento','file')}${kpi('Masa salarial',money(state.contracts.filter(c=>c.status==='Active').reduce((s,c)=>s+c.salary,0)),'Mensual demo','chart')}</div><section class="panel"><div class="panel-head"><div><h2>Contratos</h2><p>Vigencia, tipo, remuneración y documento asociado.</p></div>${can('contracts')?`<button class="btn btn-primary" data-create="contract">${ICONS.plus} Nuevo contrato</button>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Empleado</th><th>Tipo</th><th>Inicio</th><th>Fin</th><th>Salario</th><th>Estado</th><th>Documento</th><th>Acciones</th></tr></thead><tbody>${state.contracts.map(c=>`<tr><td>${esc(emp(c.employeeId)?.fullName||'—')}</td><td>${esc(c.type)}</td><td>${fmtDate(c.startDate)}</td><td>${fmtDate(c.endDate)}</td><td>${money(c.salary)}</td><td>${chip(c.status)}</td><td>${esc(c.document||'—')}</td><td>${actionButtons('contract',c.id,can('contracts'),can('contracts'))}</td></tr>`).join('')}</tbody></table></div></section>`}
  function renderPerformance(){const done=state.performance.filter(p=>p.status==='Completed');const avg=done.reduce((s,p)=>s+p.overall,0)/(done.length||1);$('view-performance').innerHTML=`<div class="kpi-grid">${kpi('Evaluaciones',state.performance.length,'Período 2026-H1','star')}${kpi('Completadas',done.length,'Ciclo actual','star')}${kpi('Pendientes',state.performance.filter(p=>p.status!=='Completed').length,'Borradores','star')}${kpi('Promedio',avg.toFixed(1)+'/5','Desempeño global','star')}</div><section class="panel"><div class="panel-head"><div><h2>Evaluaciones de desempeño</h2><p>Objetivos, competencias, liderazgo y desarrollo.</p></div>${can('performance')?`<button class="btn btn-primary" data-create="performance">${ICONS.plus} Nueva evaluación</button>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Empleado</th><th>Período</th><th>Objetivos</th><th>Competencias</th><th>Liderazgo</th><th>Resultado</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.performance.map(p=>`<tr><td>${esc(emp(p.employeeId)?.fullName||'—')}</td><td>${esc(p.period)}</td><td>${p.goals}</td><td>${p.competencies}</td><td>${p.leadership}</td><td><strong>${p.overall}/5</strong></td><td>${chip(p.status)}</td><td>${actionButtons('performance',p.id,can('performance'),can('performance'))}</td></tr>`).join('')}</tbody></table></div></section>`}
  function renderOnboarding(){$('view-onboarding').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Onboarding</h2><p>Checklist de incorporación, buddy y avance 30-60-90.</p></div>${can('onboarding')?`<button class="btn btn-primary" data-create="onboarding">${ICONS.plus} Nuevo onboarding</button>`:''}</div><div class="cards">${state.onboarding.map(o=>`<article class="card"><div class="stat-row"><div><h3>${esc(emp(o.employeeId)?.fullName||'Empleado')}</h3><div class="muted small">Inicio ${fmtDate(o.startDate)}</div></div>${chip(o.status)}</div><div class="progress"><span style="width:${o.progress}%"></span></div><div class="stat-row"><span class="muted small">Progreso</span><strong>${o.progress}%</strong></div><div class="list">${o.tasks.map((t,i)=>`<label class="list-item"><div><h4>${esc(t.name)}</h4></div><input type="checkbox" data-onboarding-task="${o.id}:${i}" ${t.done?'checked':''}></label>`).join('')}</div><div class="muted small">Buddy: ${esc(emp(o.buddyEmployeeId)?.fullName||'—')}</div>${actionButtons('onboarding',o.id,can('onboarding'),can('onboarding'))}</article>`).join('')}</div></section>`}
  function renderDocuments(){$('view-documents').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Documentos de empleados</h2><p>Documentación laboral, categorías y vencimientos.</p></div>${can('documents')?`<button class="btn btn-primary" data-create="document">${ICONS.plus} Agregar documento</button>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Empleado</th><th>Documento</th><th>Categoría</th><th>Vence</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.documents.map(d=>`<tr><td>${esc(emp(d.employeeId)?.fullName||'—')}</td><td>${esc(d.name)}</td><td>${esc(d.category)}</td><td>${fmtDate(d.expiresAt)}</td><td>${chip(d.status)}</td><td>${actionButtons('document',d.id,can('documents'),can('documents'))}</td></tr>`).join('')}</tbody></table></div></section>`}
  function renderAnnouncements(){$('view-announcements').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Comunicados internos</h2><p>Mensajes generales o segmentados por ubicación/equipo.</p></div>${can('announcements')?`<button class="btn btn-primary" data-create="announcement">${ICONS.plus} Nuevo comunicado</button>`:''}</div><div class="cards">${state.announcements.map(a=>`<article class="card"><div class="stat-row"><div><h3>${esc(a.title)}</h3><div class="muted small">${fmtDate(a.publishedAt)} · ${esc(a.audience)}</div></div>${chip(a.status)}</div><p class="muted">${esc(a.body)}</p><div class="muted small">Autor: ${esc(user(a.authorId)?.name||'—')}</div>${actionButtons('announcement',a.id,can('announcements'),can('announcements'))}</article>`).join('')}</div></section>`}
  function renderOrg(){$('view-org').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Organigrama</h2><p>Vista simplificada de áreas y referentes.</p></div></div><div class="org-tree"><div class="org-level"><div class="org-node"><div class="avatar" style="margin:0 auto 8px">AR</div><strong>Dirección General</strong><div class="muted small">HRFlow Company</div></div></div><div class="org-level">${state.departments.map(d=>`<div class="org-node"><strong>${esc(d.name)}</strong><div class="muted small">${esc(user(d.managerId)?.name||'Sin manager')}</div><div class="muted small">${state.employees.filter(e=>e.departmentId===d.id).length} personas</div></div>`).join('')}</div></div></section>`}
  function renderReports(){const deptData=state.departments.map(d=>({name:d.name,count:state.employees.filter(e=>e.departmentId===d.id&&e.status==='Active').length}));const max=Math.max(...deptData.map(x=>x.count),1);$('view-reports').innerHTML=`<div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Headcount por área</h3><p>Distribución del talento.</p></div></div><div class="list">${deptData.map(x=>`<div><div class="stat-row"><span>${esc(x.name)}</span><strong>${x.count}</strong></div><div class="progress"><span style="width:${x.count/max*100}%"></span></div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h3>Modalidad de trabajo</h3><p>Distribución por esquema laboral.</p></div></div><div class="list">${['Hybrid','On-site','Remote'].map(m=>`<div class="list-item"><span>${m}</span><strong>${state.employees.filter(e=>e.workMode===m).length}</strong></div>`).join('')}</div></section></div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Estado de contratos</h3><p>Vigencia contractual.</p></div></div><div class="list">${['Indefinite','Fixed Term','Contractor'].map(t=>`<div class="list-item"><span>${t}</span><strong>${state.contracts.filter(c=>c.type===t).length}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h3>Indicadores clave</h3><p>Resumen de People Operations.</p></div></div><div class="list"><div class="list-item"><span>Asistencia</span><strong>${attendanceRate()}%</strong></div><div class="list-item"><span>Promedio de saldo de vacaciones</span><strong>${Math.round(state.employees.reduce((s,e)=>s+e.leaveBalance,0)/state.employees.length)} días</strong></div><div class="list-item"><span>Onboarding activo</span><strong>${state.onboarding.filter(o=>o.status!=='Completed').length}</strong></div><div class="list-item"><span>Evaluaciones completadas</span><strong>${state.performance.filter(p=>p.status==='Completed').length}</strong></div></div></section></div>`}
  function renderAudit(){$('view-audit').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Auditoría</h2><p>Historial local de operaciones realizadas en el workspace.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Entidad</th><th>Detalle</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(user(a.userId)?.name||'Sistema')}</td><td><code>${esc(a.action)}</code></td><td>${esc(a.entity)}</td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></section>`}
  function renderSettings(){$('view-settings').innerHTML=`<div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Configuración general</h3><p>Preferencias del workspace.</p></div></div><form id="settingsForm" class="form-grid"><div class="form-row-2">${field('Empresa','companyName',state.settings.companyName)}${field('Zona horaria','timezone',state.settings.timezone)}</div><div class="form-row-3">${field('Inicio jornada','workdayStart',state.settings.workdayStart,'time')}${field('Fin jornada','workdayEnd',state.settings.workdayEnd,'time')}${field('Vacaciones anuales','annualLeaveDays',state.settings.annualLeaveDays,'number')}</div><div class="form-actions"><button class="btn btn-primary" type="submit">${ICONS.save} Guardar</button></div></form></section><section class="panel"><div class="panel-head"><div><h3>Respaldo y recuperación</h3><p>Exporta o restaura la información del navegador.</p></div></div><div class="list"><button class="btn btn-secondary" id="exportBackupBtn">Exportar backup JSON</button><button class="btn btn-secondary" id="importBackupBtn">Importar backup JSON</button><button class="btn btn-danger" id="restoreDemoBtn">Restaurar datos demo</button></div></section></div><section class="panel"><div class="panel-head"><div><h3>Arquitectura y seguridad</h3><p>Estado de esta edición.</p></div></div><div class="cards"><article class="card"><h4>Persistencia</h4><p class="muted">JSON de semilla + localStorage para cambios del navegador.</p></article><article class="card"><h4>Roles</h4><p class="muted">Permisos demostrativos en el front-end.</p></article><article class="card"><h4>Producción empresarial</h4><p class="muted">Para datos reales se requiere API, base de datos, autenticación segura y control de acceso en servidor.</p></article></div></section>`}
  function renderCurrent(){context();({dashboard:renderDashboard,employees:renderEmployees,departments:renderDepartments,attendance:renderAttendance,leave:renderLeave,contracts:renderContracts,performance:renderPerformance,onboarding:renderOnboarding,documents:renderDocuments,announcements:renderAnnouncements,org:renderOrg,reports:renderReports,audit:renderAudit,settings:renderSettings}[currentView]||renderDashboard)()}
  function field(label,name,value='',type='text',required=true){return `<label class="field"><span class="field-label">${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`}
  function selectField(label,name,items,value=''){return `<label class="field"><span class="field-label">${label}</span><select name="${name}">${items.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
  function textareaField(label,name,value=''){return `<label class="field"><span class="field-label">${label}</span><textarea name="${name}">${esc(value)}</textarea></label>`}
  function openModal(title,subtitle,body){$('modalTitle').textContent=title;$('modalSubtitle').textContent=subtitle;$('modalBody').innerHTML=body;$('modalOverlay').classList.remove('hidden')}
  function closeModal(){$('modalOverlay').classList.add('hidden')}
  function openDrawer(title,body){$('drawerTitle').textContent=title;$('drawerBody').innerHTML=body;$('rightDrawerOverlay').classList.remove('hidden');$('rightDrawer').classList.remove('hidden')}
  function closeDrawer(){$('rightDrawerOverlay').classList.add('hidden');$('rightDrawer').classList.add('hidden')}
  function optionsEmployees(value){return state.employees.map(e=>[e.id,`${e.fullName} · ${e.employeeCode}`])}
  function optionsDepartments(value){return state.departments.map(d=>[d.id,d.name])}
  function formFor(kind,id){
    if(kind==='employee'){const e=id?emp(id):{};openModal(id?'Editar empleado':'Nuevo empleado','Expediente laboral y datos básicos.',`<form id="entityForm" data-kind="employee" data-id="${id||''}" class="form-grid"><div class="form-row-2">${field('Nombre','firstName',e.firstName||'')}${field('Apellido','lastName',e.lastName||'')}</div><div class="form-row-3">${field('Correo','email',e.email||'','email')}${field('Teléfono','phone',e.phone||'')}${field('CI / Documento','nationalId',e.nationalId||'')}</div><div class="form-row-3">${selectField('Departamento','departmentId',optionsDepartments(),e.departmentId)}${field('Cargo','position',e.position||'')}${selectField('Estado','status',[['Active','Active'],['On Leave','On Leave'],['Inactive','Inactive']],e.status||'Active')}</div><div class="form-row-3">${selectField('Tipo','employmentType',[['Full Time','Full Time'],['Part Time','Part Time'],['Contractor','Contractor']],e.employmentType||'Full Time')}${selectField('Modalidad','workMode',[['On-site','On-site'],['Hybrid','Hybrid'],['Remote','Remote']],e.workMode||'Hybrid')}${field('Fecha ingreso','hireDate',e.hireDate||'','date')}</div><div class="form-row-3">${field('Salario','salary',e.salary||0,'number')}${field('Ubicación','location',e.location||'')}${field('Saldo vacaciones','leaveBalance',e.leaveBalance??state.settings.annualLeaveDays,'number')}</div>${field('Dirección','address',e.address||'')}${field('Contacto emergencia','emergencyContact',e.emergencyContact||'')}${field('Teléfono emergencia','emergencyPhone',e.emergencyPhone||'')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form>`)}
    if(kind==='department'){const d=id?dept(id):{};openModal(id?'Editar departamento':'Nuevo departamento','Estructura y parámetros del área.',`<form id="entityForm" data-kind="department" data-id="${id||''}" class="form-grid"><div class="form-row-2">${field('Nombre','name',d.name||'')}${field('Código','code',d.code||'')}</div><div class="form-row-3">${selectField('Responsable','managerId',state.users.map(u=>[u.id,u.name]),d.managerId)}${field('Presupuesto','budget',d.budget||0,'number')}${field('Ubicación','location',d.location||'')}</div>${selectField('Estado','status',[['Active','Active'],['Inactive','Inactive']],d.status||'Active')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form>`)}
    if(kind==='attendance'){const a=id?state.attendance.find(x=>x.id===id):{};openModal(id?'Editar asistencia':'Registrar asistencia','Control manual de jornada.',`<form id="entityForm" data-kind="attendance" data-id="${id||''}" class="form-grid">${selectField('Empleado','employeeId',optionsEmployees(),a.employeeId)}<div class="form-row-3">${field('Fecha','date',a.date||'2026-09-18','date')}${field('Entrada','checkIn',a.checkIn||'','time',false)}${field('Salida','checkOut',a.checkOut||'','time',false)}</div><div class="form-row-3">${field('Horas','hours',a.hours??8,'number')}${selectField('Estado','status',[['Present','Present'],['Late','Late'],['Absent','Absent'],['Remote','Remote']],a.status||'Present')}${field('Nota','note',a.note||'', 'text',false)}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form>`)}
    if(kind==='leave'){const l=id?state.leaves.find(x=>x.id===id):{};openModal(id?'Editar solicitud':'Nueva solicitud','Vacaciones, permiso o licencia.',`<form id="entityForm" data-kind="leave" data-id="${id||''}" class="form-grid">${selectField('Empleado','employeeId',optionsEmployees(),l.employeeId||1006)}<div class="form-row-3">${selectField('Tipo','type',[['Vacation','Vacaciones'],['Medical','Médica'],['Personal','Personal'],['Maternity/Paternity','Maternidad/Paternidad']],l.type||'Vacation')}${field('Desde','startDate',l.startDate||'','date')}${field('Hasta','endDate',l.endDate||'','date')}</div>${textareaField('Motivo','reason',l.reason||'')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Enviar solicitud</button></div></form>`)}
    if(kind==='contract'){const c=id?state.contracts.find(x=>x.id===id):{};openModal(id?'Editar contrato':'Nuevo contrato','Condiciones laborales y vigencia.',`<form id="entityForm" data-kind="contract" data-id="${id||''}" class="form-grid">${selectField('Empleado','employeeId',optionsEmployees(),c.employeeId)}<div class="form-row-3">${selectField('Tipo','type',[['Indefinite','Indefinido'],['Fixed Term','Plazo fijo'],['Contractor','Contractor']],c.type||'Indefinite')}${field('Inicio','startDate',c.startDate||'','date')}${field('Fin','endDate',c.endDate||'','date',false)}</div><div class="form-row-3">${field('Salario','salary',c.salary||0,'number')}${field('Moneda','currency',c.currency||'BOB')}${selectField('Estado','status',[['Active','Active'],['Ended','Ended']],c.status||'Active')}</div>${field('Documento','document',c.document||'', 'text',false)}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form>`)}
    if(kind==='performance'){const p=id?state.performance.find(x=>x.id===id):{};openModal(id?'Editar evaluación':'Nueva evaluación','Resultados y plan de desarrollo.',`<form id="entityForm" data-kind="performance" data-id="${id||''}" class="form-grid">${selectField('Empleado','employeeId',optionsEmployees(),p.employeeId)}<div class="form-row-3">${field('Período','period',p.period||'2026-H2')}${field('Objetivos (1-5)','goals',p.goals||3,'number')}${field('Competencias (1-5)','competencies',p.competencies||3,'number')}</div><div class="form-row-2">${field('Liderazgo (1-5)','leadership',p.leadership||3,'number')}${selectField('Estado','status',[['Draft','Draft'],['Completed','Completed']],p.status||'Draft')}</div>${textareaField('Resumen','summary',p.summary||'')}${textareaField('Plan de desarrollo','developmentPlan',p.developmentPlan||'')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form>`)}
    if(kind==='document'){const d=id?state.documents.find(x=>x.id===id):{};openModal(id?'Editar documento':'Agregar documento','Control documental del empleado.',`<form id="entityForm" data-kind="document" data-id="${id||''}" class="form-grid">${selectField('Empleado','employeeId',optionsEmployees(),d.employeeId)}<div class="form-row-3">${field('Nombre','name',d.name||'')}${field('Categoría','category',d.category||'Contract')}${field('Vence','expiresAt',d.expiresAt||'','date',false)}</div>${selectField('Estado','status',[['Valid','Valid'],['Expiring','Expiring'],['Expired','Expired']],d.status||'Valid')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form>`)}
    if(kind==='announcement'){const a=id?state.announcements.find(x=>x.id===id):{};openModal(id?'Editar comunicado':'Nuevo comunicado','Comunicación interna segmentada.',`<form id="entityForm" data-kind="announcement" data-id="${id||''}" class="form-grid">${field('Título','title',a.title||'')}<div class="form-row-2">${field('Audiencia','audience',a.audience||'All')}${selectField('Estado','status',[['Draft','Draft'],['Published','Published']],a.status||'Draft')}</div>${textareaField('Mensaje','body',a.body||'')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form>`)}
    if(kind==='onboarding'){const o=id?state.onboarding.find(x=>x.id===id):{};openModal(id?'Editar onboarding':'Nuevo onboarding','Asignación de buddy y checklist inicial.',`<form id="entityForm" data-kind="onboarding" data-id="${id||''}" class="form-grid">${selectField('Empleado','employeeId',optionsEmployees(),o.employeeId)}<div class="form-row-2">${field('Fecha inicio','startDate',o.startDate||'','date')}${selectField('Buddy','buddyEmployeeId',optionsEmployees(),o.buddyEmployeeId)}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" type="submit">Guardar</button></div></form>`)}
  }
  function upsert(kind,id,data){
    const map={employee:'employees',department:'departments',attendance:'attendance',leave:'leaves',contract:'contracts',performance:'performance',document:'documents',announcement:'announcements',onboarding:'onboarding'},key=map[kind],arr=state[key];let item={};
    if(kind==='employee'){item={...(id?emp(id):{}),id:id||nextId(arr),employeeCode:id?emp(id).employeeCode:`EMP-${nextId(arr)}`,firstName:data.firstName,lastName:data.lastName,fullName:`${data.firstName} ${data.lastName}`,email:data.email,phone:data.phone,nationalId:data.nationalId,departmentId:Number(data.departmentId),position:data.position,status:data.status,employmentType:data.employmentType,workMode:data.workMode,hireDate:data.hireDate,salary:Number(data.salary),location:data.location,leaveBalance:Number(data.leaveBalance),address:data.address,emergencyContact:data.emergencyContact,emergencyPhone:data.emergencyPhone,skills:id?emp(id).skills:[]}}
    if(kind==='department')item={id:id||nextId(arr),name:data.name,code:data.code,managerId:Number(data.managerId),budget:Number(data.budget),location:data.location,status:data.status,color:id?dept(id).color:'#0f766e'};
    if(kind==='attendance')item={id:id||nextId(arr),employeeId:Number(data.employeeId),date:data.date,checkIn:data.checkIn||null,checkOut:data.checkOut||null,hours:Number(data.hours||0),status:data.status,note:data.note||''};
    if(kind==='leave'){const days=Math.max(1,Math.floor((new Date(data.endDate)-new Date(data.startDate))/86400000)+1);item={id:id||nextId(arr),employeeId:Number(data.employeeId),type:data.type,startDate:data.startDate,endDate:data.endDate,days,status:id?state.leaves.find(x=>x.id===id).status:'Pending',reason:data.reason,requestedAt:id?state.leaves.find(x=>x.id===id).requestedAt:new Date().toISOString().slice(0,10)}}
    if(kind==='contract')item={id:id||nextId(arr),employeeId:Number(data.employeeId),type:data.type,startDate:data.startDate,endDate:data.endDate||null,salary:Number(data.salary),currency:data.currency,status:data.status,document:data.document||''};
    if(kind==='performance'){const g=Math.min(5,Math.max(1,Number(data.goals))),c=Math.min(5,Math.max(1,Number(data.competencies))),l=Math.min(5,Math.max(1,Number(data.leadership)));item={id:id||nextId(arr),employeeId:Number(data.employeeId),period:data.period,reviewerId:1001,goals:g,competencies:c,leadership:l,overall:Number(((g+c+l)/3).toFixed(1)),status:data.status,summary:data.summary,developmentPlan:data.developmentPlan}}
    if(kind==='document')item={id:id||nextId(arr),employeeId:Number(data.employeeId),category:data.category,name:data.name,expiresAt:data.expiresAt||null,status:data.status};
    if(kind==='announcement')item={id:id||nextId(arr),title:data.title,audience:data.audience,publishedAt:new Date().toISOString().slice(0,10),authorId:currentUser.id,status:data.status,body:data.body};
    if(kind==='onboarding')item={id:id||nextId(arr),employeeId:Number(data.employeeId),startDate:data.startDate,progress:id?state.onboarding.find(x=>x.id===id).progress:0,buddyEmployeeId:Number(data.buddyEmployeeId),status:'In Progress',tasks:id?state.onboarding.find(x=>x.id===id).tasks:[{name:'Documentación contractual',done:false},{name:'Alta de correo y accesos',done:false},{name:'Inducción de cultura',done:false},{name:'Presentación con equipo',done:false},{name:'Plan 30-60-90',done:false}]};
    const idx=arr.findIndex(x=>x.id===item.id);if(idx>=0)arr[idx]=item;else arr.unshift(item);log(id?'UPDATE_'+kind.toUpperCase():'CREATE_'+kind.toUpperCase(),`${kind} #${item.id}`,id?'Registro actualizado':'Registro creado');save();closeModal();renderCurrent();renderNav();toast('Información guardada','success')
  }
  function detail(kind,id){let b='';if(kind==='employee'){const e=emp(id);b=`<div class="employee-cell" style="margin-bottom:18px"><div class="avatar avatar-lg">${esc(e.firstName[0]+e.lastName[0])}</div><div><h3 style="margin:0">${esc(e.fullName)}</h3><div class="muted">${esc(e.position)} · ${esc(dept(e.departmentId)?.name||'—')}</div></div></div><div class="detail-grid">${[['Código',e.employeeCode],['Estado',e.status],['Correo',e.email],['Teléfono',e.phone],['Ingreso',fmtDate(e.hireDate)],['Modalidad',e.workMode],['Tipo',e.employmentType],['Ubicación',e.location],['Salario',money(e.salary)],['Vacaciones',e.leaveBalance+' días'],['CI',e.nationalId],['Contacto emergencia',e.emergencyContact]].map(([a,v])=>`<div class="detail-item"><span>${a}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`} else {const map={department:state.departments,attendance:state.attendance,leave:state.leaves,contract:state.contracts,performance:state.performance,onboarding:state.onboarding,document:state.documents,announcement:state.announcements};const o=map[kind]?.find(x=>x.id===id);b=`<pre style="white-space:pre-wrap;color:var(--text)">${esc(JSON.stringify(o,null,2))}</pre>`}openDrawer('Detalle',b)}
  function deleteEntity(kind,id){if(!confirm('¿Eliminar este registro?'))return;const map={employee:'employees',department:'departments',attendance:'attendance',leave:'leaves',contract:'contracts',performance:'performance',onboarding:'onboarding',document:'documents',announcement:'announcements'};const key=map[kind];if(kind==='employee'&&(state.contracts.some(c=>c.employeeId===id)||state.attendance.some(a=>a.employeeId===id))){toast('El empleado tiene registros relacionados. Cambia su estado a Inactive en lugar de eliminarlo.','error');return}state[key]=state[key].filter(x=>x.id!==id);log('DELETE_'+kind.toUpperCase(),`${kind} #${id}`,'Registro eliminado');save();renderCurrent();renderNav();toast('Registro eliminado','success')}
  function approveLeave(id,status){const l=state.leaves.find(x=>x.id===id);if(!l)return;l.status=status;if(status==='Approved'&&l.type==='Vacation'){const e=emp(l.employeeId);if(e)e.leaveBalance=Math.max(0,e.leaveBalance-l.days)}log(status==='Approved'?'APPROVE_LEAVE':'REJECT_LEAVE',`Leave #${id}`,`${status}: ${l.reason}`);save();renderLeave();renderNav();toast(`Solicitud ${status==='Approved'?'aprobada':'rechazada'}`,'success')}
  function toggleOnboarding(token){const [id,idx]=token.split(':').map(Number),o=state.onboarding.find(x=>x.id===id);if(!o)return;o.tasks[idx].done=!o.tasks[idx].done;o.progress=Math.round(o.tasks.filter(t=>t.done).length/o.tasks.length*100);o.status=o.progress===100?'Completed':'In Progress';log('UPDATE_ONBOARDING',`Onboarding #${id}`,'Checklist actualizado');save();renderOnboarding()}
  function notifications(){const items=state.notifications.filter(n=>n.role===currentUser.role||currentUser.role==='HR Admin');$('notificationsPanel').innerHTML=`<div class="panel-head" style="margin-bottom:8px"><h3>Notificaciones</h3></div>${items.length?items.map(n=>`<div class="list-item"><div><h4>${esc(n.title)}</h4><p>${esc(n.body)}</p></div></div>`).join(''):'<div class="empty">Sin notificaciones</div>'}`;$('notificationsPanel').classList.toggle('hidden')}
  function command(q=''){const term=q.toLowerCase();const res=[];state.employees.forEach(e=>{if(`${e.fullName} ${e.employeeCode} ${e.position}`.toLowerCase().includes(term))res.push({t:e.fullName,s:'Empleado',view:'employees'})});state.departments.forEach(d=>{if(d.name.toLowerCase().includes(term))res.push({t:d.name,s:'Departamento',view:'departments'})});state.leaves.forEach(l=>{if((emp(l.employeeId)?.fullName||'').toLowerCase().includes(term))res.push({t:`${emp(l.employeeId)?.fullName} · ${l.type}`,s:'Solicitud',view:'leave'})});$('commandResults').innerHTML=res.slice(0,12).map(r=>`<button class="command-result" data-command-view="${r.view}"><span><strong>${esc(r.t)}</strong><div class="muted small">${r.s}</div></span><span>↵</span></button>`).join('')||'<div class="empty">Sin resultados</div>'}
  function exportBackup(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download=`hrflow-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup exportado','success')}
  function importBackup(file){const r=new FileReader();r.onload=e=>{try{const x=JSON.parse(e.target.result);if(!DATA_FILES.every(k=>k in x))throw Error();state=x;save();renderCurrent();renderNav();toast('Backup importado','success')}catch{toast('Backup inválido','error')}};r.readAsText(file)}
  function bind(){document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav)return switchView(nav.dataset.nav);const ql=e.target.closest('[data-login]');if(ql){const u=user(ql.dataset.login);$('loginEmail').value=u.email;$('loginPassword').value=u.password;document.querySelectorAll('.quick-login-card').forEach(x=>x.classList.remove('active'));ql.classList.add('active');return}if(e.target.closest('[data-close]'))return closeModal();const cr=e.target.closest('[data-create]');if(cr)return formFor(cr.dataset.create);const ed=e.target.closest('[data-edit]');if(ed)return formFor(ed.dataset.edit,Number(ed.dataset.id));const vw=e.target.closest('[data-view]');if(vw)return detail(vw.dataset.view,Number(vw.dataset.id));const dl=e.target.closest('[data-delete]');if(dl)return deleteEntity(dl.dataset.delete,Number(dl.dataset.id));const ap=e.target.closest('[data-approve-leave]');if(ap)return approveLeave(Number(ap.dataset.approveLeave),'Approved');const rj=e.target.closest('[data-reject-leave]');if(rj)return approveLeave(Number(rj.dataset.rejectLeave),'Rejected');const cv=e.target.closest('[data-command-view]');if(cv){$('commandOverlay').classList.add('hidden');return switchView(cv.dataset.commandView)}});$('loginForm').addEventListener('submit',e=>{e.preventDefault();const u=state.users.find(x=>x.email.toLowerCase()===$('loginEmail').value.trim().toLowerCase()&&x.password===$('loginPassword').value);if(!u)return toast('Credenciales incorrectas','error');currentUser=u;save();showApp();toast(`Bienvenido, ${u.name}`,'success')});$('togglePassword').onclick=()=>{$('loginPassword').type=$('loginPassword').type==='password'?'text':'password'};$('logoutBtn').onclick=()=>{currentUser=null;localStorage.removeItem(SESSION_KEY);$('app').classList.add('hidden');$('authScreen').classList.remove('hidden')};$('themeToggle').onclick=()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';applyTheme();save()};$('notificationsBtn').onclick=notifications;$('openCommandBtn').onclick=()=>{$('commandOverlay').classList.remove('hidden');$('commandInput').focus();command('')};$('commandOverlay').onclick=e=>{if(e.target===$('commandOverlay'))$('commandOverlay').classList.add('hidden')};$('commandInput').oninput=e=>command(e.target.value);$('closeModalBtn').onclick=closeModal;$('modalOverlay').onclick=e=>{if(e.target===$('modalOverlay'))closeModal()};$('closeDrawerBtn').onclick=closeDrawer;$('rightDrawerOverlay').onclick=closeDrawer;$('mobileMenuBtn').onclick=()=>$('sidebar').classList.toggle('open');$('globalCreateBtn').onclick=()=>formFor('employee');document.addEventListener('change',e=>{if(e.target.matches('[data-onboarding-task]'))toggleOnboarding(e.target.dataset.onboardingTask)});document.addEventListener('submit',e=>{if(e.target.id==='entityForm'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target).entries());if(data.startDate&&data.endDate&&new Date(data.endDate)<new Date(data.startDate))return toast('La fecha final no puede ser anterior a la inicial','error');upsert(e.target.dataset.kind,e.target.dataset.id?Number(e.target.dataset.id):null,data)}if(e.target.id==='settingsForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());state.settings={...state.settings,...d,annualLeaveDays:Number(d.annualLeaveDays)};log('UPDATE_SETTINGS','Settings','Configuración actualizada');save();context();toast('Configuración guardada','success')}});document.addEventListener('click',e=>{if(e.target.id==='exportBackupBtn')exportBackup();if(e.target.id==='importBackupBtn')$('importBackupInput').click();if(e.target.id==='restoreDemoBtn'&&confirm('¿Restaurar datos demo?')){state=JSON.parse(JSON.stringify(window.HRFLOW_SEED));save();renderCurrent();renderNav();toast('Datos demo restaurados','success')}});$('importBackupInput').onchange=e=>{if(e.target.files[0])importBackup(e.target.files[0]);e.target.value=''};window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('commandOverlay').classList.remove('hidden');$('commandInput').focus();command('')}if(e.key==='Escape'){$('commandOverlay').classList.add('hidden');closeModal();closeDrawer()}})}
  function showApp(){$('authScreen').classList.add('hidden');$('app').classList.remove('hidden');$('sidebarAvatar').textContent=currentUser.avatar;$('sidebarUserName').textContent=currentUser.name;$('sidebarUserRole').textContent=currentUser.role;$('topbarAvatar').textContent=currentUser.avatar;$('topbarName').textContent=currentUser.name;$('topbarRole').textContent=currentUser.role;renderNav();renderCurrent()}
  async function init(){state=await load();const ses=localStorage.getItem(SESSION_KEY);if(ses){try{const s=JSON.parse(ses);currentUser=state.users.find(u=>u.id===s.userId)||null}catch{}}injectIcons();applyTheme();quickLogins();bind();if(currentUser)showApp();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('service-worker.js').catch(()=>{})}
  document.addEventListener('DOMContentLoaded',init)
})();
